/* Sample-only sortie preparation. Uses the isolated Tactical foundation; no storage. */
(function(){'use strict';
const C=window.PROCore,T=window.PROTactical,$=id=>document.getElementById(id),el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const sizes=C.UNIT_SIZES,domains=C.MOVEMENT_DOMAINS;
// Units and missions come from the Tactical pack (built-in sample for now).
const P=window.PROTacticalData;
// Owned units come from the unit lab (evolution / fusion change them); each has a uid unique among owned units.
const roster=()=>window.PROUnitLab?window.PROUnitLab.owned():P.roster().map(u=>({...u,uid:u.id}));
// Drop members that are no longer owned and follow evolutions and level-ups (same uid, new unit or stats).
function sync(){const own=new Map(roster().map(u=>[u.uid,u]));for(const g of groups){g.members=g.members.filter(m=>own.has(m.uid));for(const m of g.members)if(m.unit.id!==own.get(m.uid).id||m.unit.level!==own.get(m.uid).level){m.unit=C.clone(own.get(m.uid));setDomains(g);}}}
const scenarios=Object.fromEntries(P.missions().map(m=>[m.id,{name:m.name,goal:m.goal,surface:m.surface}]));
let missionId='training-01',sequence=2,active='group-1',groups=[{id:'group-1',name:'第1部隊',faction:'player',mode:'auto',members:[]}],lastFocus;
const scenario=()=>scenarios[missionId],current=()=>groups.find(g=>g.id===active),occupied=id=>groups.find(g=>g.members.some(m=>m.uid===id));
// anywhere: opened from the unit menu with no mission chosen, so battlefield (surface / domain) checks are skipped.
let anywhere=false,infoMode=false;
function compatibility(u,g){if(u.move===undefined||!u.movementAptitude)return 'MOVE・地形移動適性が未設定';if(anywhere)return '';try{const m={uid:u.id,unit:u};T.defaultDomain(m,scenario().surface);if(g?.mode!=='auto'&&g?.mode&&!T.supports(m,g.mode))return domains[g.mode]+'に対応していません';}catch(e){return 'この戦場の移動領域に対応していません';}return '';}
function stats(g){return g.members.length?T.formation(g):{count:0,size:0,valid:false};}
// Mission deploy rules (minimum level, banned tags, deploy_tags) apply only when a mission is chosen.
function reason(u,g){const why=(window.PROUnitLab?.crewProblem(u.uid)||'')||(u.down?(u.down==='injured'?'重傷':'大破')+'のため出撃できません（修理・治療が必要）':'')||compatibility(u,g)||(!anywhere&&window.PROUnitLab?.deployProblem(P.mission(missionId),u,u.level||1))||'';if(why)return why;return T.joinReason(g.members.map(m=>m.unit),u);}
function setDomains(g){for(const m of g.members){if(anywhere){delete m.domain;continue;}try{m.domain=g.mode==='auto'?T.defaultDomain(m,scenario().surface):g.mode;}catch(e){delete m.domain;}}}
function tell(text){$('prepNotice').textContent=text;}
function button(text,fn,cls='secondary'){const b=el('button',cls,text);b.type='button';b.onclick=fn;return b;}
function redraw(){const s=scenario();$('prepMissionName').textContent=s.name;$('prepMissionInfo').textContent='勝利条件：'+s.goal+' ｜ 基準領域：'+domains[s.surface];$('prepRosterTarget').textContent=current().name+'に追加';
 const q=$('prepSearch').value.trim().toLocaleLowerCase(),list=(sync(),roster()).filter(u=>window.PROUnitGrid.matches(u,q));
 // Map-style unit grid: tap adds to the target squad, tap an assigned unit takes it out, blocked tiles explain why.
 window.PROUnitGrid.render($('prepUnitList'),list,{search:false,selected:u=>!!occupied(u.uid),badge:u=>occupied(u.uid)?.name.replace('部隊','')||'MOVE '+(u.move??'—'),reason:u=>occupied(u.uid)?'':reason(u,current()),onPick:u=>{if(infoMode){window.PROField?.showUnit(u);return;}const owner=occupied(u.uid);if(owner){removeUnit(owner.id,u.uid);tell(u.name+'を'+owner.name+'から外しました');return;}const r=reason(u,current());if(r){tell(u.name+'：'+r);return;}addUnit(u.uid);}});
 for(const t of $('prepUnitList').querySelectorAll('.ug-tile'))t.dataset.add=t.dataset.unit;$('prepPickMode').textContent='押したとき：'+(infoMode?'情報を見る':'編成に追加・外す');
 $('prepGroups').replaceChildren();for(const g of groups){const f=stats(g),card=el('article','prep-group'+(g.id===active?' active':''));card.dataset.group=g.id;const top=el('div','prep-group-top');top.append(el('h3','',g.name),button(g.id===active?'追加先に選択中':'この部隊へ追加',()=>{active=g.id;tell(g.name+'を追加先に選択');redraw();}));card.append(top);const capacity=el('div','prep-capacity');for(const [label,value]of [['体数',f.count+' / '+T.SQUAD.count],['総サイズ',f.size+' / '+T.SQUAD.size],['部隊MOVE',g.members.length&&!anywhere?String(T.groupMove(g)):'—']]){const box=el('div');box.append(el('span','',label),el('b','',value));capacity.append(box);}card.append(capacity);const bar=el('div','prep-sizebar'),fill=el('span');fill.style.width=(f.size/8*100)+'%';bar.append(fill);card.append(bar,el('p','prep-help','残りサイズ '+(8-f.size)+' ｜ 空き体数 '+(8-f.count)));
 // Reserve squads (missions with a sortie gate): formed here, enter later from an owned gate facility.
 const rmax=anywhere?0:P.mission(missionId)?.reserveMax||0;if(rmax){const rb=button(g.reserve?'控え（出撃口から投入）':'最初から出撃',()=>{if(!g.reserve&&groups.filter(x=>x.reserve).length>=rmax){tell('控えにできるのは'+rmax+'部隊までです');return;}g.reserve=!g.reserve;redraw();},'prep-domain');rb.dataset.reserve=g.id;card.append(rb);}
 const domainButton=button('移動状態：'+(g.mode==='auto'?'自動（個体ごと）':domains[g.mode])+' ▾',()=>chooseDomain(g),'prep-domain');domainButton.disabled=!g.members.length;if(!anywhere)card.append(domainButton);
 const used=[...new Set(g.members.map(m=>m.domain).filter(Boolean))];const basis=used.includes('ground')?'ground':used.includes('water')?'water':used.includes('underwater')?'underwater':used[0];let cost='—';if(g.members.length&&g.members.every(m=>m.domain)){try{cost=String(T.stepCost(g,Object.fromEntries(Object.keys(domains).map(k=>[k,1]))));}catch(e){}}
 if(!anywhere)card.append(el('p','prep-help','移動基準：'+(domains[basis]||'—')+' ｜ 個体の移動状態：'+(used.map(k=>domains[k]).join('・')||'—')+' ｜ 基本コスト1での消費：'+cost));

 const list=el('div','prep-members');if(!g.members.length)list.append(el('p','prep-empty','一覧からユニットを追加してください。'));for(const m of g.members){const row=el('div','prep-member'),text=el('div'),why=compatibility(m.unit,g);row.dataset.uid=m.uid;text.append(el('strong','',m.unit.name),el('small','',m.unit.size+' / サイズ'+sizes[m.unit.size]+' / '+(anywhere?'領域は出撃時に決定':domains[m.domain]||'領域非対応')));if(why)text.append(el('small','prep-failed',why));const actions=el('div','actions');const move=button('移動',()=>chooseTransfer(g,m));move.disabled=groups.length<2;const sup=button(m.supply?'補給：'+P.itemName(m.supply):'補給',()=>chooseSupply(m));sup.dataset.supply=m.uid;sup.hidden=anywhere;actions.append(move,sup,button('外す',()=>removeUnit(g.id,m.uid)));row.append(text,actions);list.append(row);}card.append(list);
 if(!g.members.length&&groups.length>1)card.append(button('空の部隊を削除',()=>{groups=groups.filter(x=>x.id!==g.id);if(active===g.id)active=groups[0].id;redraw();}));$('prepGroups').append(card);}
 const nonempty=groups.filter(g=>g.members.length),front=nonempty.filter(g=>!g.reserve),errors=nonempty.flatMap(g=>g.members.filter(m=>compatibility(m.unit,g)).map(m=>g.name+'：'+m.unit.name+'が領域非対応'));const cost=sortieCost(),short=!anywhere&&window.PROUnitLab&&cost>window.PROUnitLab.credits();$('prepSummary').textContent=nonempty.length+'部隊'+(nonempty.length>front.length?'（うち控え'+(nonempty.length-front.length)+'）':'')+' / '+nonempty.reduce((n,g)=>n+g.members.length,0)+'体を編成'+(cost?' ｜ 出撃費用 '+cost.toLocaleString()+' Cr':'')+(short?' ｜ 資金が足りません':'')+(errors.length?' ｜ '+errors.join('、'):nonempty.length?(anywhere?' ｜ 編成OK':' ｜ 出撃準備OK'):' ｜ 最低1体を編成してください');$('prepConfirm').disabled=!front.length||errors.length>0||!!short;}
// Sortie cost: sum of the deployed units' sortie costs × the pack's rate (default 50%), rounded up. Paid at sortie.
function sortieCost(){const sum=groups.flatMap(g=>g.members).reduce((n,m)=>n+(Number(m.unit.sortieCost)||0),0);return Math.ceil(sum*(window.PROTacticalData?.sortieRate??50)/100);}
function addUnit(id){const u=roster().find(u=>u.uid===id),g=current();if(!u||occupied(id)||reason(u,g))return false;g.members.push({uid:id,unit:C.clone(u)});setDomains(g);tell(u.name+'を'+g.name+'に追加');redraw();return true;}
function removeUnit(gid,uid){const g=groups.find(g=>g.id===gid);g.members=g.members.filter(m=>m.uid!==uid);tell('ユニットを編成から外しました');redraw();}
function openChoice(title,choices){lastFocus=document.activeElement;$('prepChoiceTitle').textContent=title;const list=$('prepChoices');list.replaceChildren();for(const c of choices){const b=button(c.label,()=>{c.run();$('prepChoice').close();},'prep-choice');b.disabled=!!c.reason;if(c.current)b.setAttribute('aria-pressed','true');if(c.reason)b.append(el('small','',c.reason));list.append(b);}$('prepChoice').showModal();$('prepChoiceClose').focus();}
function chooseTransfer(g,m){openChoice(m.unit.name+'の移動先',groups.filter(x=>x.id!==g.id).map(target=>({label:target.name,reason:reason(m.unit,target),run:()=>{if(reason(m.unit,target))return;g.members=g.members.filter(x=>x.uid!==m.uid);target.members.push(m);setDomains(target);tell(m.unit.name+'を'+target.name+'へ移動');redraw();}})));}
// Supply (one next-sortie item per member; consumed at sortie, boosts that unit for this mission).
function chooseSupply(m){const L=window.PROUnitLab;if(!L)return;const taken=id=>groups.flatMap(g=>g.members).filter(x=>x.supply===id&&x!==m).length;openChoice(m.unit.name+'の補給',[...L.supplyItems().map(it=>({label:it.name+'（'+(it.desc||'')+'）',current:m.supply===it.id,reason:L.free(it.id)>taken(it.id)?'':'数が足りません',run:()=>{m.supply=it.id;redraw();}})),{label:'なし',current:!m.supply,run:()=>{delete m.supply;redraw();}}]);}
// Presets (4 slots): squads with their members (by owned uid) and movement modes.
function choosePreset(){const L=window.PROUnitLab;if(!L)return;const own=new Set(roster().map(u=>u.uid)),ch=[];for(let i=0;i<L.PRESETS;i++){const p=L.getPreset('tactical',i),label=p?p.groups.map(g=>g.name+'（'+g.members.length+'体）').join('・'):'空き';
 ch.push({label:'呼び出す '+(i+1)+'：'+label,reason:p?'':'保存されていません',run:()=>{groups=p.groups.map(g=>({...g,faction:'player',members:g.members.filter(uid=>own.has(uid)).map(uid=>({uid,unit:C.clone(roster().find(u=>u.uid===uid))}))}));active=groups[0].id;sequence=groups.length+1;for(const g of groups)setDomains(g);tell('プリセット'+(i+1)+'を呼び出しました');redraw();}});
 ch.push({label:'保存 '+(i+1),reason:groups.some(g=>g.members.length)?'':'編成が空です',run:()=>{L.setPreset('tactical',i,{groups:groups.map(g=>({id:g.id,name:g.name,mode:g.mode,members:g.members.map(m=>m.uid)}))});tell('プリセット'+(i+1)+'に保存しました');}});}openChoice('編成プリセット',ch);}
function chooseDomain(g){const allowed=scenario().surface==='space'?['space']:scenario().surface==='water'?['water','underwater','air']:['ground','air'];openChoice(g.name+'の移動状態',[{label:'自動（各個体の適性を優先）',current:g.mode==='auto',run:()=>{g.mode='auto';setDomains(g);redraw();}},...allowed.map(domain=>({label:domains[domain],current:g.mode===domain,reason:T.canSwitch(g,domain)?'':'部隊の全個体が対応している必要があります',run:()=>{if(!T.canSwitch(g,domain))return;g.mode=domain;setDomains(g);tell(domains[domain]+'へ切替');redraw();}}))]);}
$('prepAddGroup').onclick=()=>{const id='group-'+sequence;groups.push({id,name:'第'+sequence+'部隊',faction:'player',mode:'auto',members:[]});sequence++;active=id;tell('新しい部隊を追加しました');redraw();const list=$('prepGroups');list.scrollTop=list.scrollHeight;};$('prepSearch').oninput=redraw;$('prepPickMode').onclick=()=>{infoMode=!infoMode;redraw();};$('prepChoiceClose').onclick=()=>$('prepChoice').close();$('prepChoice').addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
$('prepConfirm').onclick=()=>{if($('prepConfirm').disabled)return;const snap=window.PROPreparation.snapshot(),L=window.PROUnitLab,cost=sortieCost();if(cost&&L)L.spend(cost);
 // Supply items are consumed here and boost their member for this mission.
 for(const g of snap.groups)for(const m of g.members){if(m.supply&&L?.consumeItem(m.supply))m.unit=L.applySupply(m.unit,m.supply);delete m.supply;}for(const g of groups)for(const m of g.members)delete m.supply;window.PROField.deploy(snap);location.hash='#map';};
$('prepPresets').onclick=choosePreset;
window.PROPreparation={setMission(id,{formationOnly=false}={}){// Formation from the unit menu has no mission; a selected Dispatch mission must not leave the list stale.
if(!scenarios[id]){if(!formationOnly)return;id=missionId;}const was=anywhere;anywhere=formationOnly;if(missionId!==id||was!==anywhere){missionId=id;for(const g of groups){g.mode='auto';setDomains(g);}}tell('');redraw();},snapshot:()=>C.clone({missionId,active,groups}),addUnit};redraw();
})();
